/* @autogenerated */
import { TemplateRepository } from 'app/features/template/template/repository/template-repository.service';
import { BulkEditField } from 'app/shared/toolkit/bulk-edit/bulk-edit.model';
import { BaseBulkEditAction } from 'app/shared/toolkit/action/base-bulk-edit-action';
import { Template } from 'app/features/template/template/model/template.model';
import { BulkEditDialogData } from 'app/shared/toolkit/bulk-edit/bulk-edit-dialog.component';
import { Component, inject } from '@angular/core';

/** Edición masiva de template: los campos que se pueden cambiar en bloque. */
@Component({ selector: 'template-view-bulk-edit-action', standalone: false, template: '' })
export class TemplateViewBulkEditActionComponent extends BaseBulkEditAction<Template> {
  readonly name = 'bulkEdit';
  protected readonly scope = 'template/template';
  protected readonly repository = inject(TemplateRepository);

  protected override keyOf(item: Template): string {
    return String(item.uid);
  }

  /** Los campos que se pueden editar en bloque y el tipo de cada uno. */
  protected bulkFields(): readonly BulkEditField<Template>[] {
    return [
      { name: 'code', label: this.text('fieldCode'), type: 'text' },
      { name: 'tenant', label: this.text('fieldTenant'), type: 'relation', optional: true },
      { name: 'theme', label: this.text('fieldTheme'), type: 'text', optional: true },
      {
        name: 'channel',
        label: this.text('fieldChannel'),
        type: 'enum',
        options: [
          { value: 'mail', label: 'MAIL' },
          { value: 'sms', label: 'SMS' },
          { value: 'html', label: 'HTML' },
        ],
      },
    ];
  }

  protected override toDialogData(count: number): BulkEditDialogData<Template> {
    return {
      title: this.text('dialogTitle'),
      count,
      singular: this.text('selectedSingular'),
      plural: this.text('selectedPlural'),
      confirm: this.text('confirm'),
      cancel: this.text('cancel'),
      fields: this.bulkFields(),
    };
  }
}
